n(voltage); // Print the voltage.\n  delay(1); // Delay 1ms\n}\n"})}),"\n",(0,i.jsx)(t.p,{children:(0,i.jsx)(t.strong,{children:"\u7D50\u679C"})}),"\n",(0,i.jsx)("p",{style:{textAlign:"center"},children:(0,i.jsx)("img",{src:"https://files.seeedstudio.com/wiki/Seeeduino-XIAO/img/THonny_DAC.jpg",alt:"pir",width:600,height:"auto"})}),"\n",(0,i.jsx)(t.h2,{id:"\u30D0\u30C3\u30C6\u30EA\u30FC\u306E\u4F7F\u7528",children:"\u30D0\u30C3\u30C6\u30EA\u30FC\u306E\u4F7F\u7528"}),"\n",(0,i.jsx)(t.admonition,{type:"note",children:(0,i.jsx)(t.p,{children:"\u80CC\u9762\u306B BAT \u30D0\u30C3\u30BF\u30FC\u30EA\u30FC\u30B3\u30CD\u30AF\u30BF\u3092\u5099\u3048\u3066\u3044\u308B\u306E\u306F XIAO SAMD21 Plus \u306E\u307F\u3067\u3059\u306E\u3067\u3001\u3054\u6CE8\u610F\u304F\u3060\u3055\u3044\u3002"})}),"\n",(0,i.jsx)(t.p,{children:"XIAO SAMD21 Plus \u306F\u30013.7V \u30EA\u30C1\u30A6\u30E0\u30D0\u30C3\u30C6\u30EA\u30FC\u3092\u96FB\u6E90\u5165\u529B\u3068\u3057\u3066\u4F7F\u7528\u3067\u304D\u307E\u3059\u3002\u914D\u7DDA\u65B9\u6CD5\u306B\u3064\u3044\u3066\u306F\u3001\u6B21\u306E\u56F3\u3092\u53C2\u7167\u3057\u3066\u304F\u3060\u3055\u3044\u3002"}),"\n",(0,i.jsx)("div",{style:{textAlign:"center"},children:(0,i.jsx)("img",{src:"https://files.seeedstudio.com/wiki/Seeeduino-XIAO/img/battery.png",style:{width:800,height:"auto"}})}),"\n",(0,i.jsx)("br",{}),"\n",(0,i.jsx)(t.admonition,{type:"caution",children:(0,i.jsx)(t.p,{children:"\u306F\u3093\u3060\u4ED8\u3051\u306E\u969B\u306B\u306F\u3001\u30D7\u30E9\u30B9\u7AEF\u5B50\u3068\u30DE\u30A4\u30CA\u30B9\u7AEF\u5B50\u3092\u77ED\u7D61\u3055\u305B\u3066\u30D0\u30C3\u30C6\u30EA\u30FC\u3084\u6A5F\u5668\u3092\u713C\u640D\u3055\u305B\u306A\u3044\u3088\u3046\u3001\u5341\u5206\u6CE8\u610F\u3057\u3066\u304F\u3060\u3055\u3044\u3002\u30D0\u30C3\u30C6\u30EA\u30FC\u306B\u96FB\u529B\u304C\u6B8B\u3063\u3066\u3044\u308B\u5834\u5408\u306F\u3001\u6C7A\u3057\u3066\u57FA\u677F\u306B\u306F\u3093\u3060\u4ED8\u3051\u3057\u306A\u3044\u3067\u304F\u3060\u3055\u3044\u3002\u57F